    "v8": "sw_en",
    "v9": "is_5g",
    "v11": "alt_vendor_info_byte"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "driver start/stop flag"
    },
    {
      "offset": 1,
      "meaning": "vendor_info source selector"
    },
    {
      "offset": 2,
      "meaning": "vendor_info byte used when selector is clear"
    },
    {
      "offset": 3,
      "meaning": "5G enable flag"
    },
    {
      "offset": 188,
      "meaning": "RF/driver state byte for sw_en or 5G status"
    },
    {
      "offset": 178,
      "meaning": "RF/driver state word; bit 14 appears to force or mark 5G mode"
    }
  ]
}
